from h import build
R=[
(3151182,"Scones salés au cheddar et à la sauge",
"Plus riches en protéines que certaines collations, ces scones pourraient constituer une belle gâterie pendant la dialyse.",
"8",None,
["350 g de farine ordinaire","1 cuillère à café de crème de tartre","½ cuillère à café de bicarbonate de soude","50 g de beurre non salé","100 g de cheddar, râpé","1 cuillère à café de sauge séchée","1 œuf, battu","250 ml de lait de soja biologique"],
["Chauffez le four à 190 °C / 170 °C chaleur tournante / thermostat gaz 5. Chemisez une plaque de cuisson. Dans un bol, mélangez la farine, la crème de tartre et le bicarbonate de soude, puis incorporez le beurre du bout des doigts jusqu'à obtenir une texture de chapelure fine.","Incorporez 80 g du cheddar râpé et la sauge séchée. Faites un puits au centre et versez le lait. À l'aide d'un couteau, en un mouvement de coupe, mélangez pour former une pâte.","Farinez votre plan de travail et vos mains, démoulez la pâte et travaillez-la jusqu'à ce qu'elle soit lisse, puis façonnez-la en une forme ronde d'environ 3 cm d'épaisseur. Déposez-la sur la plaque de cuisson et marquez 8 pointes. Badigeonnez d'œuf battu et saupoudrez des 20 g de cheddar restants.","Faites cuire 20 minutes jusqu'à ce qu'ils soient dorés. Meilleurs servis tièdes avec un peu de beurre."],
[["Note du chef","Une savoureuse alternative salée au petit pain avec une soupe, ou à déguster dans votre boîte à lunch."],["Glucides","La principale source de glucides est la farine de ces scones; les valeurs en glucides sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","La crème de tartre est une source de potassium, mais elle contient moins de phosphate que la poudre à pâte. La quantité utilisée permet de consommer cette recette comme collation occasionnelle dans le cadre d'un régime pauvre en potassium.\nLe lait de soja biologique contient moins de phosphate et de potassium que le lait de vache; il est donc utilisé ici pour réduire la teneur en phosphate et en potassium.\nLe fromage et les produits de boulangerie sont souvent riches en phosphate; prenez donc un chélateur du phosphate avec cette collation si on vous en a prescrit un."],["Protéines","Les ingrédients des scones (lait, œuf et cheddar) font qu'ils ne conviendraient pas à une personne suivant un régime pauvre en protéines."],["Sans gluten","Utilisez de la farine sans gluten."],["Option plus saine","Utilisez de la farine de blé entier et du fromage allégé."],["Conservation","Se conservent trois jours dans un contenant hermétique au réfrigérateur."]],
[]),
(3154406,"Petits chaussons à la courge musquée et au fromage de chèvre",
"Faire bouillir les légumes dans ce plat aide à réduire le potassium, mais grâce à l'ajout de fromage de chèvre, il reste beaucoup de saveur.",
"4",None,
["1 abaisse de pâte feuilletée prête à dérouler","1 courge musquée, pelée et coupée en cubes","1 grosse patate douce, pelée et coupée en cubes","1 petit oignon, haché","5 g de graines de sésame ou de graines d'oignon","1 cuillère à café d'huile d'olive","60 g de fromage de chèvre frais","1 œuf, battu","Une pincée de poivre noir moulu",["Pour servir","240 g de laitue, tranchée"],["Pour servir","80 g de concombre, tranché"]],
["Préchauffez le four à 180 °C / 160 °C chaleur tournante / thermostat gaz 4. Mettez la patate douce et la courge musquée dans une casserole, couvrez d'eau et portez à ébullition; faites cuire jusqu'à ce qu'elles soient tendres.","Égouttez la patate douce et la courge musquée et versez-les dans un plat à rôtir avec l'oignon haché. Arrosez d'huile d'olive, saupoudrez de poivre noir et faites cuire au four 20 minutes. Sortez du four et laissez refroidir.","Coupez la pâte en 8 rectangles égaux. Placez 4 rectangles sur une plaque de cuisson chemisée et déposez à la cuillère ¼ du mélange de légumes au centre de chaque rectangle, en laissant un espace sur tout le pourtour. Garnissez chaque portion de légumes de 15 g de fromage de chèvre émietté. Badigeonnez d'un peu d'œuf battu le bord de la pâte sur tout le pourtour.","Prenez les 4 rectangles restants, pliez-les sans serrer en deux dans le sens de la longueur et faites 5 fentes dans les deux épaisseurs en laissant une bordure. Dépliez et déposez sur les 4 chaussons, en pressant les bords sur les bords dorés à l'œuf de la couche du dessous pour sceller vos chaussons.","Badigeonnez le dessus de dorure à l'œuf, saupoudrez de graines de sésame ou de graines d'oignon et faites cuire 25 minutes jusqu'à ce qu'ils soient dorés. Une fois cuits, sortez du four.","Une fois cuits, sortez du four et servez avec la salade verte."],
[["Note du chef","Un plat délicieux, rapide et facile à préparer."],["Glucides","Les principales sources de glucides de ce repas sont la patate douce, la courge musquée et la pâte. Les valeurs en glucides sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Nous avons fait bouillir la courge musquée et la patate douce plutôt que de les cuire au four afin de réduire la teneur en potassium.\nIl n'y a qu'une petite quantité de fromage frais dans ce plat pour fournir du phosphate; la teneur globale en phosphate est donc faible."],["Protéines","Ce plat est faible en protéines; vous pourriez envisager de doubler le fromage afin d'augmenter les protéines tout en conservant un repas faible en potassium et en phosphate."],["Sans gluten","Utilisez de la pâte sans gluten."],["Végane","Utilisez du fromage végane."],["Option plus saine","La pâte est riche en matières grasses; pour une option plus saine, vous pourriez omettre la couche de pâte du dessus et préparer des chaussons ouverts."],["Astuces","La courge musquée et la patate douce sont offertes déjà préparées dans le rayon des surgelés de la plupart des supermarchés si vous trouvez difficile de les peler à la maison."]],
[]),
(3162079,"Wraps César au poulet",
"Un délicieux wrap riche en protéines, adapté aux reins et à la boîte à lunch. Il est aussi faible en potassium et en phosphate, donc idéal à emporter à la dialyse.",
"4",None,
["175 g de poulet cuit","50 g de mayonnaise","1 gousse d'ail, écrasée","1 morceau de parmesan de 50 g","100 g de laitue iceberg, grossièrement hachée","¼ cuillère à café de sauce Worcestershire","Poivre noir","4 tortillas souples"],
["Effilochez le poulet cuit en lanières et mettez-le dans un bol avec les feuilles de laitue hachées et l'ail écrasé.","Râpez de fines tranches de parmesan dans le bol, puis ajoutez la mayonnaise et la sauce Worcestershire et mélangez délicatement, en assaisonnant de poivre.","Pour assembler les wraps, déposez à la cuillère ¼ du mélange sur la moitié inférieure d'une tortilla. Repliez le bas de la tortilla sur la garniture.","Faites deux plis de chaque côté et roulez fermement. Répétez avec les trois autres tortillas. Mangez entier ou coupé en deux pour servir immédiatement, ou enveloppez dans du papier d'aluminium pour le garder entier jusqu'au moment de le manger."],
[["Note du chef","La classique salade César a été revisitée en wrap, ce qui en fait le lunch rapide ou le souper léger parfait."],["Glucides","La principale source de glucides de ce plat provient de la tortilla. La valeur en glucides de ce plat est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Si vous respectez les tailles de portion indiquées dans cette recette, ce plat est faible à la fois en potassium et en phosphate. Le poulet et le parmesan contiennent tous deux du phosphate, mais la petite portion utilisée dans cette recette maintient une faible teneur globale en phosphate. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Le poulet et le fromage utilisés dans cette recette fournissent une source de protéines, excellente pour les personnes sous dialyse et pour quiconque doit manger plus de protéines."],["Sans gluten","Utilisez des tortillas sans gluten."],["Végétarien","Utilisez plutôt des morceaux sans viande style poulet ou des pois chiches. Vérifiez que votre parmesan convient aux végétariens."],["Végane","Utilisez plutôt des morceaux sans viande style poulet ou des pois chiches. Utilisez une mayonnaise sans produits laitiers appropriée et un fromage à pâte dure de style italien sans produits laitiers."],["Option plus saine","Aucun sel n'est ajouté dans cette recette. Le parmesan, la sauce Worcestershire, la mayonnaise et les tortillas contiennent du sel, ce qui place cette recette légèrement au-dessus de la limite pour être classée comme plat faible en sel. Pour réduire au minimum la teneur en sel, choisissez les tortillas les moins salées. Mesurez la sauce Worcestershire, la mayonnaise et le parmesan afin d'éviter d'en ajouter trop. Pour réduire encore davantage la teneur en sel, vous pourriez envisager d'utiliser une cuillère à café de jus de citron à la place de la sauce Worcestershire et du yogourt nature à la place de la mayonnaise.\nSi vous souhaitez réduire les matières grasses de ce plat, choisissez une mayonnaise légère.\nUtiliser un wrap de blé entier augmentera les fibres dans votre alimentation."],["Conservation","Une fois préparés, gardez-les au réfrigérateur et consommez-les dans les deux jours. Si vous les emportez pour le lunch, nous recommandons d'utiliser un bloc réfrigérant pour les garder frais."],["Astuces","Si vous n'avez pas besoin de quatre portions, vous pouvez réduire la recette."]],
[]),
(3194515,"Salade de haricots et de couscous",
"Un plat pauvre en protéines et facile à préparer. Il fait un excellent repas du midi et est faible en potassium, en phosphate et en sel.",
"2",None,
["1 cuillère à soupe d'huile d'olive","1 oignon rouge, finement haché","150 g de couscous","240 ml de bouillon de légumes à faible teneur en sel","1 poivron rouge, coupé en morceaux de 1 cm","400 g de salade de trois haricots en conserve, dans l'eau","10 g de persil frais, haché (facultatif)"],
["Hachez l'oignon et le poivron et mettez de côté.","Préparez le bouillon de légumes et mesurez le couscous. Incorporez le bouillon de légumes chaud au couscous, couvrez et laissez reposer cinq minutes.","Faites chauffer l'huile d'olive dans une petite casserole. Faites revenir l'oignon à feu doux pendant cinq minutes ou jusqu'à ce qu'il soit tendre, puis retirez la casserole du feu.","Découvrez le couscous et égrenez-le à la fourchette. Ajoutez l'oignon cuit et le poivron frais, puis égouttez la salade de haricots et ajoutez-la au couscous. Mélangez délicatement jusqu'à ce que le tout soit bien mélangé. Si vous utilisez du persil, saupoudrez-en la salade avant de servir."],
[["Note du chef","Une salade de haricots et de couscous végane facile, qui peut être préparée à l'avance pour un lunch santé."],["Glucides","Les principales sources de glucides de ce plat proviennent du couscous et des haricots. La valeur en glucides de ce plat est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Les haricots contiennent du potassium et du phosphate, mais avec la quantité utilisée dans cette recette, les teneurs globales sont faibles. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Cette recette est faible en protéines, ce qui est excellent pour les personnes à qui l'on a conseillé de réduire leurs protéines. Si on vous a conseillé d'augmenter vos protéines, vous pouvez ajouter une petite boîte de thon. Cherchez du thon dans l'eau de source et égouttez-le avant de l'utiliser."],["Sans gluten","Utilisez du sarrasin ou du quinoa et un bouillon de légumes sans gluten pour une option sans gluten."],["Conservation","Ce plat se conserve bien et peut être gardé au réfrigérateur jusqu'à 3 jours."]],
[]),
(3204614,"Crevettes poivrées des Caraïbes et riz au lait de coco",">","4",None,
["450 g de crevettes (crues ou cuites)","Un tour de moulin de poivre noir","1 cuillère à soupe de fécule de maïs","2 piments rouges forts, finement coupés en dés","1 botte d'oignons verts (partie blanche et verte), finement coupés en dés","1 cuillère à soupe d'huile végétale","3 gousses d'ail, hachées","240 g de riz à grains longs, rincé","1 boîte de 400 ml de lait de coco","1 cuillère à soupe d'huile de coco","30 g de coriandre fraîche, grossièrement hachée",["Salade d'accompagnement à servir","80 g de laitue, grossièrement déchirée"],["Salade d'accompagnement à servir","50 g de concombre, tranché"],["Salade d'accompagnement à servir","2 tomates, tranchées"],["Salade d'accompagnement à servir","1 poivron, tranché"],["Salade d'accompagnement à servir","Vinaigrette à faible teneur en sel"]],
["Préparez le riz en mettant le lait de coco et l'huile de coco dans une casserole et portez à ébullition. Ajoutez le riz, ramenez à ébullition, puis réduisez le feu à doux et couvrez la casserole. Faites cuire le riz jusqu'à ce que tout le liquide soit absorbé. Retirez du feu et laissez reposer quelques minutes.","Pendant la cuisson du riz, mélangez les crevettes avec la fécule de maïs, le poivre noir, le paprika et les flocons de piment. Faites chauffer la moitié de l'huile dans une poêle à feu moyen et faites sauter les crevettes – juste brièvement pour les réchauffer si vous utilisez des crevettes cuites; plus longtemps si vous utilisez des crevettes crues, afin de vous assurer qu'elles sont bien cuites.","Dans une autre poêle, faites chauffer le reste de l'huile à feu moyen-doux et faites cuire les piments, les oignons verts (partie blanche seulement) et l'ail pendant environ 3 minutes. Ajoutez les crevettes cuites, ainsi que les parties vertes des oignons verts, et mélangez le tout. Les crevettes sont déjà cuites; il ne s'agit donc que de les mélanger rapidement.","Préparez la salade d'accompagnement en mélangeant la laitue, le concombre, les tomates et le poivron et assaisonnez avec votre vinaigrette préférée.","Servez les crevettes sur le riz au lait de coco, avec un peu de coriandre fraîche et la salade en accompagnement."],
[["Note du chef","Un plat de crevettes rapide et facile, faible en phosphate, en potassium et en sel."],["Glucides","Le riz est la principale source de glucides, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Phosphate/potassium","Cette recette est faible en potassium si vous respectez les quantités et les tailles de portion indiquées; elle convient donc si on vous a conseillé de réduire la quantité de potassium dans votre alimentation. Elle est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par les crevettes; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette fournit une source de protéines. Si on vous conseille de manger plus de protéines, envisagez d'en consommer davantage dans les autres repas de la journée."],["Salubrité des aliments","Si vous utilisez des crevettes crues, assurez-vous qu'elles sont bien cuites afin d'éviter tout risque d'infection."],["Suggestion de service","Ce plat se déguste de préférence fraîchement préparé."],["Option plus saine","Si vous souhaitez rendre ce plat plus faible en matières grasses, envisagez d'utiliser du lait de coco léger ou à teneur réduite en matières grasses."]],
[]),
(3227420,"Salade asiatique de poulet collant",">","2",None,
["150 g de chair de poitrine de poulet crue","1 gousse d'ail, écrasée","1 cuillère à soupe de sauce soja à teneur réduite en sel","1 cuillère à soupe de miel ou de sirop d'érable","150 g de chou blanc, finement émincé","1 cuillère à soupe d'huile de sésame","2 carottes, pelées et finement râpées","3 oignons verts, finement tranchés en tronçons","¼ de concombre, coupé en fins bâtonnets","Une petite poignée de feuilles de menthe","40 g d'amandes ou d'arachides nature non salées, hachées, grossièrement hachées","1 cuillère à soupe de graines de sésame, grillées","100 g de nouilles de riz sèches"],
["Placez la poitrine de poulet entre deux feuilles de pellicule plastique et aplatissez-la avec un rouleau à pâtisserie. Tranchez le poulet en lanières.","Mélangez la sauce soja, le miel, l'ail et la moitié de l'huile de sésame dans un bol et fouettez pour bien mélanger. Mettez le poulet dans la marinade, mélangez bien, couvrez et réfrigérez au moins 20 minutes.","Faites chauffer le reste de l'huile de sésame dans une poêle à feu moyen-vif, puis ajoutez les lanières de poulet et faites-les frire jusqu'à ce qu'elles soient complètement cuites. Retirez le poulet de la poêle et réservez-le dans une assiette.","Réduisez le feu et ajoutez le reste du mélange de marinade et faites cuire jusqu'à obtenir une sauce collante, environ 5 minutes. Laissez refroidir.","Faites bouillir une bouilloire pleine d'eau et versez l'eau bouillante dans un bol. Mettez les nouilles dans l'eau et laissez-les 3 minutes. Égouttez.","Versez les autres ingrédients dans un bol et incorporez délicatement le poulet et les nouilles. Servez avec la sauce arrosée sur le dessus."],
[["Note du chef","Une salade savoureuse d'inspiration asiatique, faible en sel, en potassium et en phosphate."],["Glucides","Les nouilles de riz sont la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium si vous respectez les quantités des ingrédients et les tailles de portion. Elle convient donc aux personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation. Cette recette est aussi faible en phosphate, mais elle en contient un peu (principalement fourni par le poulet et les noix); si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette fournit une source de protéines. Pour une option plus pauvre en protéines, envisagez de réduire le poulet à 75 g et d'ajouter une petite boîte (200 g) de pois chiches égouttés à l'étape 6."],["Astuces","L'huile de sésame coûte plus cher, mais elle en vaut la peine, car une petite quantité ajoute une saveur merveilleuse. La sauce soja à teneur réduite en sel contient tout de même du sel; mesurez donc avec soin."]],
[]),
(3236439,"Tartelettes de pâte phyllo aux cerises",
"Un dessert parfait, qui convient à tout le monde.",
"6",None,
["250 g de cerises dénoyautées surgelées","75 g de sucre granulé","1 cuillère à café d'essence de vanille","1 cuillère à soupe de poudre d'arrow-root","1 cuillère à soupe d'eau","1 boîte de pâte phyllo prête à l'emploi (environ 250 g)","1 cuillère à soupe d'huile","60 g de beurre","1 cuillère à soupe de sucre glace"],
["Mettez les cerises surgelées, le sucre et l'essence de vanille dans une casserole. Faites cuire à feu moyen pendant 5 minutes, en remuant fréquemment. Écrasez délicatement les cerises avec une spatule. Mélangez la poudre d'arrow-root et l'eau pour former une pâte.","Ajoutez la pâte aux cerises cuites en remuant au fur et à mesure. Portez à ébullition, puis retirez du feu et laissez refroidir. Préchauffez le four à 190 °C / 170 °C chaleur tournante / thermostat gaz 5 et graissez un moule à muffins.","Prenez trois feuilles de pâte et coupez chacune en quatre carrés. Faites fondre le beurre et badigeonnez la pâte de chaque côté, puis garnissez six alvéoles avec deux carrés dans chacune. Ajoutez une cuillère à soupe de garniture aux cerises dans chacune. Repliez les bords de la pâte phyllo sur la garniture aux cerises pour fermer sans serrer.","Badigeonnez chaque tartelette de beurre supplémentaire. Faites cuire au four 10 à 15 minutes, jusqu'à ce que la pâte soit brun doré clair partout. Sortez du four et transférez sur une grille de refroidissement. Une fois refroidies, saupoudrez de sucre glace. Servez tièdes ou à température ambiante."],
[["Note du chef","L'utilisation de cerises surgelées et de pâte prête à l'emploi permet de préparer ces tartelettes pour les occasions spéciales toute l'année."],["Glucides","Les principales sources de glucides de ce plat sont les cerises, les sucres et la pâte phyllo. La valeur en glucides est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette contient des cerises, qui sont riches en potassium, mais utilisées dans la quantité indiquée dans la recette, elle reste un plat faible en potassium.\nCe plat contient une petite quantité de phosphate qui provient principalement de la pâte phyllo. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est faible en protéines et constitue un dessert approprié pour une occasion spéciale si on vous a conseillé de suivre un régime pauvre en protéines."],["Sans gluten","Il est parfois difficile de trouver de la pâte phyllo prête à l'emploi sans gluten; vous pouvez donc utiliser de la pâte feuilletée sans gluten à la place."],["Végane","Beaucoup de pâtes phyllo prêtes à l'emploi ne contiennent pas de produits laitiers. Utilisez une tartinade sans produits laitiers à la place du beurre."],["Option plus saine","Si vous voulez réduire la quantité de sucre ou de matières grasses que vous consommez, réduisez la quantité de sucre utilisée dans la garniture aux cerises, ou remplacez-la par un édulcorant. Envisagez d'utiliser une tartinade faible en gras à la place du beurre."],["Option plus économique","L'extrait de vanille peut être utilisé à la place des gousses de vanille."],["Conservation","Une fois refroidies, conservez-les dans un contenant hermétique au réfrigérateur et consommez-les dans les deux jours."]],
[]),
(3240039,"Œufs et légumes au four",">","2",None,
["1 cuillère à café d'huile végétale","4 œufs, battus","Poivre noir","½ cuillère à café de fines herbes mélangées séchées ou de flocons de piment","250 g de légumes surgelés mélangés, décongelés et égouttés","30 g de cheddar, râpé",["Pour servir","4 tranches de pain"],["Pour servir","20 g de beurre non salé"]],
["Préchauffez le four à 180 °C. Huilez une petite poêle allant au four ou un petit plat de cuisson. Fouettez un peu de poivre noir et les fines herbes ou les flocons de piment dans les œufs. Versez les œufs dans la poêle.","Versez les légumes dans le mélange d'œufs et incorporez-les.","Répartissez le fromage sur le dessus et faites cuire au four 12 à 15 minutes ou jusqu'à ce que le dessus soit légèrement doré.","Sortez du four et laissez reposer de côté quelques minutes. Faites griller le pain, tartinez-le de beurre et servez."],
[["Note du chef","Ce plat de type frittata, faible en potassium et en phosphate, est simple et rapide."],["Glucides","Le pain est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium; elle convient donc aux personnes à qui l'on a conseillé de suivre un régime pauvre en potassium. Cette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par les œufs et le fromage; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse."],["Option plus saine","Bien qu'aucun sel n'ait été ajouté, cette recette n'est pas faible en sel. Cela s'explique par le fait que le pain et le fromage contiennent du sel – vous voudrez peut-être vérifier la quantité de sel dans votre pain et choisir celui qui en contient le moins"]],
[]),
(3246751,"Gâteau de fête",">","12 portions pour adultes",None,
[["Pâte à gâteau","200 g de beurre non salé, ramolli"],["Pâte à gâteau","200 g de sucre extra-fin"],["Pâte à gâteau","200 g de farine ordinaire"],["Pâte à gâteau","4 œufs"],["Pâte à gâteau","1 cuillère à café de bicarbonate de soude"],["Pâte à gâteau","1 cuillère à café de crème de tartre"],["Pâte à gâteau","50 ml de lait"],["Pâte à gâteau","2 cuillères à café d'essence de vanille"],["Glaçage au beurre","150 g de beurre non salé, ramolli"],["Glaçage au beurre","300 g de sucre glace"],["Glaçage au beurre","Vermicelles, colorant et décorations au goût"]],
["Préchauffez le four à 170 °C / 150 °C chaleur tournante / thermostat gaz 3. Préparez votre plaque ou vos moules : pour un gâteau en plaque, graissez et chemisez (papier sulfurisé) un moule de 20 cm x 30 cm; pour un gâteau à étages rond, graissez et farinez 2 moules à gâteau de 17.5 cm de diamètre; pour des petits gâteaux, garnissez un moule à muffins de caissettes.","Battez le beurre et le sucre ensemble jusqu'à ce que le mélange soit pâle et mousseux. Ajoutez la farine, les œufs, le bicarbonate, la crème de tartre, le lait et la vanille, en battant de nouveau jusqu'à consistance lisse.","Versez le mélange dans la plaque, les moules ou les caissettes appropriés. Temps de cuisson : gâteau en plaque : 40 à 45 minutes; gâteaux : 23 à 25 minutes; petits gâteaux : 18 à 20 minutes. Faites cuire toutes les options jusqu'à ce qu'une brochette en ressorte propre. Sortez du four et laissez refroidir dans la plaque, les moules ou les caissettes.","Préparez le glaçage. Battez le beurre jusqu'à ce qu'il soit mou, puis incorporez le sucre glace en battant. Si vous voulez ajouter de la couleur ou de la saveur, faites-le maintenant. Vous pouvez étaler le glaçage au couteau, ou le mettre dans une poche à douille et décorer à la poche. Pour le gâteau, utilisez une partie du glaçage au beurre au milieu, puis assemblez les deux gâteaux l'un sur l'autre et décorez le dessus avec le reste de la crème au beurre. Ajoutez les décorations de votre choix."],
[["Note du chef","Cette recette polyvalente, adaptée aux reins, peut être préparée en gâteau, en petits gâteaux ou en gâteau en plaque et convient parfaitement aux anniversaires ou à d'autres célébrations."],["Conseils sur les portions pour les enfants","Les portions sont basées sur des portions d'adulte.\nCette recette de gâteau de fête donne 12 portions pour adultes.\nVoici un guide pour les enfants :\nTout-petit (1 à 4 ans) : ¼ de portion\nJeune enfant (5 à 9 ans) : ½\nEnfant plus âgé (10 à 13 ans) : ¾\nAdolescents (14 ans et plus) : 1\nCertains enfants ont un appétit plus grand que d'autres. La portion de votre enfant pourrait devoir être adaptée à son alimentation habituelle si vous pensez que les portions recommandées sont trop grandes ou trop petites. Nous vous conseillons d'en parler avec votre diététiste avant d'augmenter la portion si votre enfant a de la difficulté à maîtriser son potassium ou son phosphate."],["Glucides","La farine et le sucre sont la principale source de glucides, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Phosphate/potassium","Cette recette est faible en potassium si vous respectez les quantités des ingrédients et les tailles de portion. Elle est aussi faible en phosphate, mais elle en contient un peu, principalement provenant de la farine; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Option plus saine","Il s'agit d'une recette riche en énergie, à déguster à l'occasion dans le cadre d'une alimentation équilibrée. Servez avec des baies ou un autre fruit pour contribuer à en augmenter la valeur nutritive."],["Sans gluten","Utilisez de la farine sans gluten."],["Conservation","Une fois refroidi, conservez dans un contenant hermétique pendant 5 jours."],["Astuces","Cette recette polyvalente peut être adaptée à différentes occasions – habillez-la ou gardez-la simple ! Elle est faible en sel, en potassium et en phosphate, ce qui en fait une délicieuse gâterie que tout le monde peut savourer à l'occasion. L'utilisation d'agents levants faibles en phosphate, comme le bicarbonate de soude et la crème de tartre, aide à garder les gâteaux et les petits gâteaux faibles en phosphate et adaptés aux reins."]],
[]),
(3253638,"Riz frit aux œufs, aux asperges et aux pommes",
"Un plat végétarien très rapide, faible en sel, en protéines, en potassium et en phosphate.",
"4",None,
["300 g de riz jasmin","2 cuillères à soupe d'huile de tournesol","4 gousses d'ail, écrasées ou hachées","1 morceau de gingembre de 1 pouce, finement haché","1 oignon rouge, haché","3 oignons verts, tranchés (en séparant les parties blanche et verte)","2 tomates moyennes, hachées","220 g d'asperges, coupées (en séparant les tiges et les pointes)","2 pommes, coupées en cubes","4 œufs, battus dans un bol","2 cuillères à soupe de sauce soja à teneur réduite en sel","1 cuillère à soupe d'huile de sésame","1 petite poignée de coriandre fraîche, grossièrement hachée","2 piments (facultatif), tranchés"],
["Préparez tous les ingrédients, puis faites cuire le riz selon les instructions sur l'emballage, mais évitez de trop le cuire – vous voulez que le riz reste légèrement ferme sous la dent. Une fois prêt, égouttez et mettez de côté.","Faites chauffer 1 cuillère à soupe d'huile dans une grande poêle ou un wok à feu moyen. Une fois chaud, ajoutez les œufs et brouillez-les doucement avec un peu de poivre noir. Mettez de côté dans un bol une fois cuits.","Faites chauffer la poêle ou le wok avec le reste de l'huile. Ajoutez l'ail et le gingembre et faites cuire à feu vif, en remuant constamment, pendant 1 à 2 minutes, jusqu'à ce qu'ils soient parfumés et légèrement dorés.","Ajoutez l'oignon rouge, les parties blanches des oignons verts et les tomates. Faites cuire en remuant pendant 5 minutes. Ajoutez les tiges d'asperges et faites cuire en remuant pendant 1 minute. Ajoutez ensuite les pointes d'asperges et les pommes, et faites cuire encore 1 à 2 minutes.","Ajoutez le riz en paquets, puis utilisez des cuillères en bois ou des spatules pour remuer, mélanger et défaire le riz. Faites frire en remuant constamment pendant 3 minutes.","Ajoutez la sauce soja, les œufs cuits, les parties vertes hachées des oignons verts et la coriandre hachée. Mélangez. Ajoutez ensuite l'huile de sésame, mélangez, et ajoutez le piment tranché, le cas échéant. Servez."],
[["Note du chef","Un riz frit aux œufs entièrement végétarien, avec un mariage d'asperges et de pommes."],["Glucides","Le riz est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré l'utilisation de certains ingrédients riches en potassium, comme les asperges et les tomates, cette recette est très faible en potassium si l'on respecte les quantités des ingrédients et les tailles de portion. Elle convient donc aux personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation.\nCette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par l'œuf; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est faible en protéines; elle convient donc aux personnes à qui l'on a conseillé de manger moins de protéines. Si on vous a conseillé de manger plus de protéines, vous pourriez ajouter 200 à 300 g de morue cuite."],["Option plus économique","Utilisez du riz à grains longs au lieu du riz jasmin."],["Sans gluten","Utilisez une sauce soja sans gluten."],["Option plus saine","Utilisez du riz brun plutôt que du riz blanc pour fournir plus de fibres."],["Conservation","Ce plat se déguste de préférence fraîchement préparé."]],
[]),
]
